import { useState } from "react";
import {
  handleDeleteImage,
  handleDeleteAll,
  confirmDeleteAction,
} from "./deleteActions";
import { toggleImageStatus } from "./updateActions";

const DialogCom = ({
  setRefetch,
  setGetLogos,
  GetLogos,
  openGallery,
  setOpenGallery,
  getSlider,
  getStoredPhotos,
  getGalleryPhoto,
  setGetSlider,
  setGetStoredPhotos,
  setGetGalleryPhoto,
}) => {
  const [editMode, setEditMode] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(null);
  const [loading, setLoading] = useState(false);
  const [indicator, setIndicator] = useState(false);

  const deleteParams = {
    confirmDelete,
    setIndicator,
    setLoading,
    setConfirmDelete,
    setRefetch,
    setGetSlider,
    setGetStoredPhotos,
    setGetGalleryPhoto,
    setGetLogos,
  };

  return (
    <>
      {/* Toggle Image Status */}
      <button onClick={() => toggleImageStatus("GalleryPhoto", "example.jpg", setLoading, setGetGalleryPhoto, setGetLogos, setGetSlider, setGetStoredPhotos)}>
        Toggle Image Status
      </button>

      {/* Delete Functions */}
      <button onClick={() => handleDeleteImage("GalleryPhoto", "example.jpg", setConfirmDelete)}>
        Delete Single Image
      </button>
      <button onClick={() => handleDeleteAll("GalleryPhoto", setConfirmDelete)}>
        Delete All
      </button>
      <button onClick={() => confirmDeleteAction(deleteParams)}>
        Confirm Delete
      </button>
    </>
  );
};

export default DialogCom;
